// Dangling Pointer from Heap Deallocation
int *p_heap = malloc(sizeof(int));
*p_heap = 10;
free(p_heap);         // Memory freed

// Access attempt: *p_heap; // UB

// Dangling Pointer from Scope Exit
int *p_scope;
{
    int stack_var = 50;
    p_scope = &stack_var;
} // stack_var destroyed, p_scope is invalid

// Mitigation: Nulling Pointers
p_heap = NULL;

// Robust Safety Check
if (p_heap == NULL) {
    // Handle error or skip access
}
